INSERT INTO `score_history` (`id`, `user_id`, `level`, `skill`, `score`, `max_score`, `taken_at`, `breakdown`, `detailed_results`) VALUES ('6aa8be6779009aa42a8b3a59', '69fd846f3e85023bf9f1ec6e', 1, 'full_test', 2, 100, '2026-09-14 20:41:27', '{"listening":{"score":0,"max":25,"label":"การฟัง"},"speaking":{"score":0,"max":15,"label":"การพูด"},"reading":{"score":0,"max":30,"label":"การอ่าน"},"writing":{"score":2,"max":30,"label":"การเขียน"}}', '[{"id":1,"section":"ส่วนที่ 1: การฟัง (คำศัพท์)","type":"mcq","question":"ข้อ 1. คำว่า \\"สร้อย\\" อ่านอย่างไร ?","user_answer":"","correct_answer":"ข. ส้อย","is_correct":false},{"id":2,"section":"ส่วนที่ 1: การฟัง (คำศัพท์)","type":"mcq","question":"ข้อ 2. คำว่า \\"ปลอดภัย\\" อ่านอย่างไร ?","user_answer":"","correct_answer":"ก. ปลอด-พัย","is_correct":false},{"id":3,"section":"ส่วนที่ 1: การฟัง (คำศัพท์)","type":"mcq","question":"ข้อ 3. คำว่า \\"ภูมิปัญญา\\" อ่านอย่างไร ?","user_answer":"","correct_answer":"ข. พูม-ปัน-ยา","is_correct":false},{"id":4,"section":"ส่วนที่ 1: การฟัง (ประกาศ)","type":"mcq","question":"ข้อ 4. ข้อใดเป็นคำเตือนจากประกาศนี้ ?","user_answer":"","correct_answer":"ก. ห้ามว่ายน้ำ","is_correct":false},{"id":5,"section":"ส่วนที่ 1: การฟัง (ประกาศ)","type":"mcq","question":"ข้อ 5. ข้อใดที่ท่านควรพึงปฏิบัติ ?","user_answer":"","correct_answer":"ข. แยกขยะก่อนทิ้ง","is_correct":false},{"id":6,"section":"ส่วนที่ 1: การฟัง (ประกาศ)","type":"mcq","question":"ข้อ 6. ข้อใดไม่ควรปฏิบัติ ?","user_answer":"","correct_answer":"ข. ตะโกนบอกเพื่อนว่าทำเสร็จแล้ว","is_correct":false},{"id":7,"section":"ส่วนที่ 1: การฟัง (นิทาน)","type":"mcq","question":"ข้อ 7. พ่อค้าบรรทุกสิ่งใดไว้บนหลังลาในครั้งแรก ?","user_answer":"","correct_answer":"ก. กระสอบเกลือ","is_correct":false},{"id":8,"section":"ส่วนที่ 1: การฟัง (นิทาน)","type":"mcq","question":"ข้อ 8. เพราะเหตุใดลาจึงรู้สึกว่าของเบาลง หลังจากตกน้ำครั้งแรก ?","user_answer":"","correct_answer":"ข. เกลือละลายไปกับน้ำ","is_correct":false},{"id":9,"section":"ส่วนที่ 1: การฟัง (นิทาน)","type":"mcq","question":"ข้อ 9. ข้อคิดจากนิทานเรื่องนี้ตรงกับข้อใด ?","user_answer":"","correct_answer":"ก. ความเจ้าเล่ห์เพื่อเลี่ยงงานหนัก มักนำมาซึ่งความลำบากที่มากกว่าเดิม","is_correct":false},{"id":10,"section":"ส่วนที่ 1: การฟัง (คำศัพท์)","type":"mcq","question":"ข้อ 10. คำศัพท์ที่ฟังตรงกับข้อใด ?","user_answer":"","correct_answer":"ข. กงสุล","is_correct":false},{"id":11,"section":"ส่วนที่ 1: การฟัง (คำศัพท์)","type":"mcq","question":"ข้อ 11. คำศัพท์ที่ฟังตรงกับข้อใด ?","user_answer":"","correct_answer":"ก. วาทศิลป์","is_correct":false},{"id":12,"section":"ส่วนที่ 1: การฟัง (สำนวน)","type":"mcq","question":"ข้อ 12. สำนวนนี้มีความหมายตรงกับข้อใด ?","user_answer":"","correct_answer":"ง. ทำหลายอย่างพร้อมกันจนไม่สำเร็จสักอย่าง","is_correct":false},{"id":13,"section":"ส่วนที่ 1: การฟัง (สำนวน)","type":"mcq","question":"ข้อ 13. สำนวนนี้มีความหมายตรงกับข้อใด ?","user_answer":"","correct_answer":"ก. รีบทำเมื่อมีโอกาสดี","is_correct":false},{"id":14,"section":"ส่วนที่ 1: การฟัง (สำนวน)","type":"mcq","question":"ข้อ 14. สำนวนนี้มีความหมายตรงกับข้อใด ?","user_answer":"","correct_answer":"ง. ไม่ช่วยแล้วยังขัดขวางผู้อื่น","is_correct":false},{"id":15,"section":"ส่วนที่ 1: การฟัง (เด็กติดจอ)","type":"tf","question":"ข้อ 15","user_answer":"","correct_answer":"เท็จ","is_correct":false},{"id":16,"section":"ส่วนที่ 1: การฟัง (เด็กติดจอ)","type":"tf","question":"ข้อ 16","user_answer":"","correct_answer":"เท็จ","is_correct":false},{"id":17,"section":"ส่วนที่ 1: การฟัง (เด็กติดจอ)","type":"tf","question":"ข้อ 17","user_answer":"","correct_answer":"จริง","is_correct":false},{"id":18,"section":"ส่วนที่ 1: การฟัง (เด็กติดจอ)","type":"tf","question":"ข้อ 18","user_answer":"","correct_answer":"จริง","is_correct":false},{"id":19,"section":"ส่วนที่ 1: การฟัง (เด็กติดจอ)","type":"tf","question":"ข้อ 19","user_answer":"","correct_answer":"จริง","is_correct":false},{"id":20,"section":"ส่วนที่ 1: การฟัง (ประกาศภัยหนาว)","type":"mcq","question":"ข้อ 20. จุดประสงค์หลักของประกาศนี้คืออะไร ?","user_answer":"","correct_answer":"ข. เตือนให้เตรียมรับมือกับภัยหนาว","is_correct":false},{"id":21,"section":"ส่วนที่ 1: การฟัง (ประกาศภัยหนาว)","type":"mcq","question":"ข้อ 21. กลุ่มเป้าหมายหลักของประกาศนี้คือใคร ?","user_answer":"","correct_answer":"ง. เกษตรกรและผู้เลี้ยงสัตว์","is_correct":false},{"id":22,"section":"ส่วนที่ 1: การฟัง (โฆษณา)","type":"mcq","question":"ข้อ 22. คำพูดในข้อใดมีลักษณะเป็น การโฆษณาเกินจริง ?","user_answer":"","correct_answer":"ก. จดจำแม่นยำเหมือนวัยหนุ่มสาว","is_correct":false},{"id":23,"section":"ส่วนที่ 1: การฟัง (โฆษณา)","type":"mcq","question":"ข้อ 23. หาก \\"สมชาย\\" จะตัดสินใจซื้อผลิตภัณฑ์นี้อย่างมีวิจารณญาณ ควรทำสิ่งใดเป็นอันดับแรก ?","user_answer":"","correct_answer":"ง. ตรวจสอบเลขทะเบียน อย. และงานวิจัยที่อ้างถึง","is_correct":false},{"id":24,"section":"ส่วนที่ 1: การฟัง (ความหมายและการสะกดคำ)","type":"mcq","question":"ข้อ 24. คำว่า \\"ขัน\\" คำแรก มีความหมายตรงกับข้อใด ?","user_answer":"","correct_answer":"ก. ภาชนะตักน้ำ","is_correct":false},{"id":25,"section":"ส่วนที่ 1: การฟัง (ความหมายและการสะกดคำ)","type":"mcq","question":"ข้อ 25. คำที่อยู่ในมาตราตัวสะกด แม่เกย มีกี่คำ (ไม่นับคำซ้ำ) ?","user_answer":"","correct_answer":"ค. 3 คำ","is_correct":false},{"id":26,"section":"ส่วนที่ 2: การพูด (แนะนำตัว)","type":"speaking","question":"\\"สวัสดีค่ะ คุณชื่ออะไรคะ\\"","user_answer":"","correct_answer":"","is_correct":false},{"id":27,"section":"ส่วนที่ 2: การพูด (แนะนำตัว)","type":"speaking","question":"\\"คุณเป็นคนที่ไหนคะ (บ้านเกิดอยู่ที่ไหน)\\"","user_answer":"","correct_answer":"","is_correct":false},{"id":28,"section":"ส่วนที่ 2: การพูด (แนะนำตัว)","type":"speaking","question":"\\"คุณเรียนจบระดับไหน และจบจากที่ไหนมาคะ\\"","user_answer":"","correct_answer":"","is_correct":false},{"id":29,"section":"ส่วนที่ 2: การพูด (แนะนำตัว)","type":"speaking","question":"\\"ตอนนี้คุณทำงานอะไร หรือทำอาชีพอะไรอยู่คะ\\"","user_answer":"","correct_answer":"","is_correct":false},{"id":30,"section":"ส่วนที่ 2: การพูด (แนะนำตัว)","type":"speaking","question":"\\"เวลาว่างคุณชอบทำกิจกรรมอะไรมากที่สุดคะ\\"","user_answer":"","correct_answer":"","is_correct":false},{"id":31,"section":"ส่วนที่ 2: การพูด (สถานการณ์จำลอง)","type":"speaking","question":"ข้อ 31","user_answer":"","correct_answer":"","is_correct":false},{"id":32,"section":"ส่วนที่ 2: การพูด (สถานการณ์จำลอง)","type":"speaking","question":"ข้อ 32","user_answer":"","correct_answer":"เลี้ยว, ตรง, ซ้าย, ขวา, เดิน, ขับ","is_correct":false},{"id":33,"section":"ส่วนที่ 2: การพูด (สถานการณ์จำลอง)","type":"speaking","question":"ข้อ 33","user_answer":"","correct_answer":"ปวด, เจ็บ, ไข้, ไอ, น้ำมูก, เวียน, ร้อน, หนาว","is_correct":false},{"id":34,"section":"ส่วนที่ 2: การพูด (สถานการณ์จำลอง)","type":"speaking","question":"ข้อ 34","user_answer":"","correct_answer":"กวาด, ขยะ, ถุง, ไม้, ถัง, น้ำ, เช็ด, ถู","is_correct":false},{"id":35,"section":"ส่วนที่ 2: การพูด (สถานการณ์จำลอง)","type":"speaking","question":"ข้อ 35","user_answer":"","correct_answer":"บ้าน, ห้องสมุด, โรงเรียน, ร้าน, คาเฟ่","is_correct":false},{"id":36,"section":"ส่วนที่ 2: การพูด (อ่านออกเสียง)","type":"speaking","question":"ชามเขียวคว่ำเช้า ชามขาวคว่ำค่ำ","user_answer":"","correct_answer":"ชามเขียวคว่ำเช้า ชามขาวคว่ำค่ำ","is_correct":false},{"id":37,"section":"ส่วนที่ 2: การพูด (อ่านออกเสียง)","type":"speaking","question":"สำลีขายหวย สำรวยขายสี สำลีเล่นหวย สำรวยเล่นสี","user_answer":"","correct_answer":"สำลีขายหวย สำรวยขายสี สำลีเล่นหวย สำรวยเล่นสี","is_correct":false},{"id":38,"section":"ส่วนที่ 2: การพูด (อ่านออกเสียง)","type":"speaking","question":"ยายกินลำไย น้ำลายยายไหลย้อย","user_answer":"","correct_answer":"ยายกินลำไย น้ำลายยายไหลย้อย","is_correct":false},{"id":39,"section":"ส่วนที่ 2: การพูด (อ่านออกเสียง)","type":"speaking","question":"เช้าฟาดผัดฟัก เย็นฟาดฟักผัด","user_answer":"","correct_answer":"เช้าฟาดผัดฟัก เย็นฟาดฟักผัด","is_correct":false},{"id":40,"section":"ส่วนที่ 2: การพูด (อ่านออกเสียง)","type":"speaking","question":"กินมันติดเหงือก กินเผือกติดฟัน","user_answer":"","correct_answer":"ก